CCData.products.forEach(product => {
  if(laptopAccessorySubcategories[product.id]) {
    product.catalogSubCategory = laptopAccessorySubcategories[product.id];
  }
});

CCData.products.forEach(product => {
  if(product.id === 32) {
    product.mainCategory = "CCTV Sales, Installation & Service";
    product.subCategory = "CCTV Sales, Installation & Service";
    product.catalogSubCategory = "Cameras";
  }
  if(product.id === 33) {
    product.mainCategory = "UPS Sales, Installation & Service";
    product.subCategory = "UPS Sales, Installation & Service";
    product.catalogSubCategory = "UPS Systems";
  }
});

CCData.products.forEach(product => {
  if(product.subCategory === "Laptop Accessories") {
    product.image = localCatalogImage("vikash-laptop-accessory.jpg");
  } else if(product.subCategory === "Raspberry Pi & Accessories") {
    product.image = localCatalogImage("silverline-category.png");
  } else if(product.subCategory === "Laptops & Desktops") {
    product.image = product.type === "PERIPHERAL"
      ? localCatalogImage("aarna-monitor.png")
      : product.type === "DESKTOP" || product.type === "GAMING DESKTOP"
        ? localCatalogImage("aarna-cpu.png")
        : localCatalogImage("aarna-motherboard.png");
  }
});

if(typeof window !== 'undefined') {
  const saved = localStorage.getItem('cctech_db_version');
  if(saved !== CCData.version) {
    localStorage.removeItem('cctech_db');
    localStorage.setItem('cctech_db_version', CCData.version);
  }
  if(localStorage.getItem('cctech_db')) {
    try {
      const local = JSON.parse(localStorage.getItem('cctech_db'));
      if(Array.isArray(local.products)) CCData.products = local.products;
      if(Array.isArray(local.services)) CCData.services = local.services;
      if(Array.isArray(local.categories)) CCData.categories = local.categories;
    } catch (e) {
      console.warn('Unable to parse saved database:', e);
    }
  }
}
